const LOOPBACK_HOSTS = new Set(["localhost", "127.0.0.1", "::1"]);
const POSTGRES_PROTOCOLS = new Set(["postgres:", "postgresql:"]);

function normalizeHost(host) {
  return String(host).trim().toLowerCase().replace(/^\[|\]$/g, "");
}

function parseDatabaseTarget(value) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new TypeError("A non-empty PostgreSQL URL is required");
  }
  const url = new URL(value.trim());
  if (!POSTGRES_PROTOCOLS.has(url.protocol)) {
    throw new TypeError("Only postgres:// or postgresql:// URLs are supported");
  }
  if (url.searchParams.has("service")) {
    throw new TypeError("PostgreSQL service-file URLs are not allowed by the suite runner");
  }

  const database = decodeURIComponent(url.pathname.replace(/^\/+/, ""));
  if (!database || database.includes("/") || database.includes("\\") || database.includes("\0")) {
    throw new TypeError("The PostgreSQL URL must name exactly one database");
  }

  const hostInputs = [url.hostname, ...url.searchParams.getAll("host"), ...url.searchParams.getAll("hostaddr")];
  const hosts = hostInputs.flatMap((value) => String(value).split(",").map(normalizeHost));
  if (hosts.some((host) => host === "")) {
    throw new TypeError("Every PostgreSQL connection host must be explicit");
  }

  const queryPorts = url.searchParams.getAll("port");
  if (queryPorts.length > 1) throw new TypeError("Multiple PostgreSQL port overrides are not allowed");
  const rawPort = queryPorts.at(-1) || url.port || "5432";
  const port = Number(rawPort);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new TypeError("The PostgreSQL port must be in the range 1-65535");
  }

  return { hosts: [...new Set(hosts)].sort(), port, database };
}

export function isLoopbackPostgresUrl(value) {
  try {
    return parseDatabaseTarget(value).hosts.every((host) => LOOPBACK_HOSTS.has(host));
  } catch {
    return false;
  }
}

export function samePostgresDatabase(first, second) {
  try {
    const a = parseDatabaseTarget(first);
    const b = parseDatabaseTarget(second);
    return a.port === b.port && a.database === b.database && a.hosts.length === b.hosts.length && a.hosts.every((host, index) => host === b.hosts[index]);
  } catch {
    return false;
  }
}

export function assertUniqueServicePorts(services) {
  const owners = new Map();
  for (const service of services) {
    const port = Number(service.port);
    if (!Number.isInteger(port) || port < 1 || port > 65535) {
      throw new TypeError(`${service.label} has an invalid TCP port`);
    }
    if (owners.has(port)) {
      throw new Error(`Port ${port} is assigned to both ${owners.get(port)} and ${service.label}`);
    }
    owners.set(port, service.label);
  }
  return true;
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  assertUniqueServicePorts,
  isLoopbackPostgresUrl,
  samePostgresDatabase,
} from "./suite-policy.mjs";

test("accepts explicit loopback PostgreSQL URLs with a database name", () => {
  assert.equal(isLoopbackPostgresUrl("postgresql://[REDACTED]@localhost:5432/tessera_test"), true);
  assert.equal(isLoopbackPostgresUrl("postgres://[REDACTED]@127.0.0.1/tessera_test"), true);
  assert.equal(isLoopbackPostgresUrl("postgresql://[REDACTED]@[::1]:5433/tessera_test"), true);
});

test("rejects empty hosts, missing database names, non-PostgreSQL protocols, and remote hosts", () => {
  assert.equal(isLoopbackPostgresUrl("postgresql:///tessera_test?host=localhost"), false);
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost"), false);
  assert.equal(isLoopbackPostgresUrl("https://localhost/tessera_test"), false);
  assert.equal(isLoopbackPostgresUrl("postgresql://db.example.com/tessera_test"), false);
});

test("rejects remote host and hostaddr query overrides even when the URL hostname is local", () => {
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost/tessera_test?host=db.example.com"), false);
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost/tessera_test?hostaddr=10.0.0.4"), false);
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost/tessera_test?host=localhost,10.0.0.4"), false);
});

test("rejects service-file indirection and malformed ports", () => {
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost/tessera_test?service=production"), false);
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost:99999/tessera_test"), false);
  assert.equal(isLoopbackPostgresUrl("postgresql://localhost/tessera_test?port=5432&port=5433"), false);
});

test("detects the same database target regardless of credentials or postgres scheme alias", () => {
  assert.equal(
    samePostgresDatabase("postgres://[REDACTED]@localhost:5432/tessera", "postgresql://[REDACTED]@localhost/tessera"),
    true,
  );
  assert.equal(samePostgresDatabase("postgresql://localhost/tessera", "postgresql://localhost/other"), false);
  assert.equal(samePostgresDatabase("postgresql://localhost/tessera", "postgresql://127.0.0.1/tessera"), false);
});

test("rejects duplicate service ports before starting any child process", () => {
  assert.equal(assertUniqueServicePorts([{ label: "web", port: "3000" }, { label: "api", port: 5000 }]), true);
  assert.throws(
    () => assertUniqueServicePorts([{ label: "web", port: "3000" }, { label: "api", port: 3000 }]),
    /assigned to both web and api/,
  );
  assert.throws(() => assertUniqueServicePorts([{ label: "bad", port: 0 }]), /invalid TCP port/);
});

/**
 * Repeatable eval record writer.
 *
 * Writes JSON {sha, date_ct, model, suite, n, pass, cost_usd} from measured
 * inputs. It does not run a quiz and does not invent scores. Suite names that
 * claim MMLU or MMLU-Pro are refused: homemade quizzes are not those benchmarks.
 *
 * Usage:
 *   node scripts/eval/write-result.mjs \
 *     --sha <git-sha> --model <name> --suite <name> \
 *     --n <int> --pass <int> --cost-usd <number> [--out <file>]
 */
import { writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const MMLU_NAME = /mmlu/i;

export function assertNotIndustryMmlu(suite) {
  if (typeof suite !== "string" || suite.trim() === "") {
    throw new Error("suite must be a non-empty name");
  }
  if (MMLU_NAME.test(suite)) {
    throw new Error(
      `Refusing suite name ${JSON.stringify(suite)}: homemade quizzes are not MMLU or MMLU-Pro`,
    );
  }
}

export function formatDateCt(date = new Date()) {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-US", {
      timeZone: "America/Chicago",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(date)
      .map((part) => [part.type, part.value]),
  );
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second} CT`;
}

export function buildEvalRecord({ sha, dateCt, model, suite, n, pass, costUsd }) {
  if (typeof sha !== "string" || sha.trim() === "") {
    throw new Error("sha is required");
  }
  if (typeof model !== "string" || model.trim() === "") {
    throw new Error("model is required");
  }
  assertNotIndustryMmlu(suite);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("n must be a non-negative integer");
  }
  if (!Number.isInteger(pass) || pass < 0 || pass > n) {
    throw new Error("pass must be an integer from 0 through n");
  }
  if (typeof costUsd !== "number" || !Number.isFinite(costUsd) || costUsd < 0) {
    throw new Error("cost_usd must be a finite number >= 0");
  }
  return {
    sha,
    date_ct: dateCt ?? formatDateCt(),
    model,
    suite,
    n,
    pass,
    cost_usd: costUsd,
  };
}

function readFlag(argv, name) {
  const index = argv.indexOf(name);
  if (index === -1) return undefined;
  return argv[index + 1];
}

